{
  "translations": {
    "L0001": "No le pedí a Lan que borrara la foto.",
    "L0002": "El teléfono sigue en el bolsillo.",
    "L0003": "Lan solo cambió el nombre de la carpeta.",
    "L0004": "Le pedí a Lan que no borrara la foto.",
    "L0005": "La petición posterior es distinta de la anterior.",
    "L0006": "Nadie le ha enviado todavía la foto a mamá."
  },
  "sourceNotes": [
    {
      "sourceID": "L0002",
      "sourceQuote": "Điện thoại vẫn nằm trong túi.",
      "kind": "ambiguous_reading",
      "explanation": "«Túi» puede referirse a un bolsillo o a un bolso; el contexto no permite precisarlo. Se ha optado por «bolsillo»."
    }
  ]
}
